method add_elements(arr: seq<int>, k: int) returns (sum: int)
    requires |arr| > 0 && 1 <= k <= |arr|
    ensures sum == SumOfTwoDigitElements(arr, k)

    // Auxiliary function to compute the sum of elements with at most two digits
    function SumOfTwoDigitElements(arr: seq<int>, k: int): int
        requires |arr| > 0 && 1 <= k <= |arr|
        ensures 0 <= SumOfTwoDigitElements(arr, k) <= 999
    {
        var total := 0;
        var count := 0;

        // Iterate over the first k elements of arr
        while count < k
            invariant 0 <= count <= k
            invariant total == SumOfTwoDigitElements(arr[0..count])
        {
            if abs(arr[count]) < 100 {
                total := total + arr[count];
            }
            count := count + 1;
        }
        return total;
    }
